ALLOWED=("LIST_DOMAINS","GET_DOMAIN","SEARCH_DOMAINS","CLASSIFY_SERVICE","VALIDATE_MAPPING","HEALTH")
PROHIBITED=("EXECUTE_GRID_OPERATIONS","CONTROL_PLANT_OR_DAM","DISPATCH_POWER","OPERATE_UTILITY_NETWORK","ISSUE_ENVIRONMENTAL_PERMITS","GUARANTEE_APPROVAL","TRADE_ENERGY","PROCESS_PAYMENTS","STORE_SECRETS")
def is_allowed(operation): return operation.strip().upper() in ALLOWED
def summary(): return {"allowed_operations":list(ALLOWED),"prohibited_operations":list(PROHIBITED),"mode":"METADATA_AND_CLASSIFICATION_ONLY"}
